<?php if($user['role']==='owner'): ?><form method="post" class="formgrid"><?php formFields('tax.prepare') ?><input type="hidden" name="entity_id" value="<?= h($p['id']) ?>"><input type="hidden" name="version" value="<?= h($p['profile_version']??'') ?>"><label>VAT number<input name="vat_number" value="<?= h($p['vat_number']??'') ?>" maxlength="20" required></label><label>Полное имя sole trader<input name="proprietor" value="<?= h($p['proprietor']??'') ?>" maxlength="180" required></label><label>Контакты продавца<input name="contact" value="<?= h($p['contact']??'') ?>" maxlength="180" required></label><label>Адрес вручения юридических документов<input name="service_address" value="<?= h($p['service_address']??'') ?>" maxlength="500" required></label><label>Начало действия<input name="effective_on" type="date" value="<?= h(ukToday()) ?>" required></label><label>Проверено до<input name="reviewed_until" type="date" value="<?= h($p['reviewed_until']??(new \DateTimeImmutable(ukToday()))->modify('+90 days')->format('Y-m-d')) ?>" required></label><button class="primary">Передать бухгалтеру (блокирует выставление до согласования)</button></form><?php endif ?>
<?php if($p['profile_version']): ?><p>VAT <?= h($p['vat_number']) ?> · <?= h($p['proprietor']) ?> · <?= h($p['contact']) ?> · <?= h($p['service_address']) ?> · <?= h($p['effective_on']) ?> — <?= h($p['reviewed_until']) ?></p><?php endif ?>
<?php if($user['role']==='accountant'&&$p['profile_version']&&!$p['approved_at']): ?><form method="post" class="formgrid"><?php formFields('tax.approve') ?><input type="hidden" name="entity_id" value="<?= h($p['id']) ?>"><input type="hidden" name="version" value="<?= h($p['profile_version']) ?>"><label>Ссылка/номер свидетельства проверки и эталонных примеров<input name="review_reference" required maxlength="500"></label><label><input type="checkbox" name="confirmed" value="1" required> Проверены регистрация, реквизиты, применимость UK standard VAT и контрольные расчёты, включая кредит-ноту</label><button class="primary">Подтвердить профиль</button></form><?php endif ?></details><?php endforeach ?></section>
<section class="panel"><h2>Реестр исходящего VAT</h2><form method="get" class="filters"><input type="hidden" name="p" value="tax"><label>С<input type="date" name="from" value="<?= h($from) ?>" required></label><label>По<input type="date" name="to" value="<?= h($to) ?>" required></label><button>Сформировать</button></form><p><a href="<?= h(url('tax.export',['from'=>$from,'to'=>$to])) ?>">Скачать CSV для бухгалтера</a> · Счетов без VAT-пакета за период: <?= h($legacy) ?> (не включены, проверьте отдельно).</p><?php foreach($totals as $eid=>$t): ?><p>Продавец #<?= h($eid) ?> · Без VAT: <?= h(money($t['net'])) ?> GBP · Исходящий VAT: <?= h(money($t['vat'])) ?> GBP · С VAT: <?= h(money($t['gross'])) ?> GBP</p><?php endforeach ?>
<div class="tablewrap"><table><thead><tr><th>Документ</th><th>Дата</th><th>Редакция</th><th>Без VAT</th><th>VAT</th><th>С VAT</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= h(url('tax.print',['project'=>$r['project_id'],'id'=>$r['invoice_id'],'credit'=>$r['kind']==='credit'?1:0])) ?>"><?= h($r['doc_number']) ?></a></td><td><?= h($r['date']) ?></td><td><?= h($r['rule_version']) ?></td><td><?= h(money($r['net'])) ?></td><td><?= h(money($r['vat'])) ?></td><td><?= h(money($r['gross'])) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>Пакет юрисдикции и обмен с бухгалтером</h2><p>Редакции расчёта (не даты изменения закона): <?php foreach(UK_RULES as $ruleId=>$rule): ?><?= h($ruleId) ?> (<?= h($rule['from']) ?> — <?= h($rule['until']??'действующая') ?>); <?php endforeach ?></p><p>Не является отправкой декларации HMRC. Сохранённые файлы доступны для независимой проверки; повторная выгрузка не изменяет ранее сохранённые байты.</p>
<form method="post" class="formgrid"><?php formFields('tax.exchange') ?><label>Юрлицо<select name="entity_id" required><?php foreach($profiles as $p): if(!$p['profile_version'])continue; ?><option value="<?= h($p['id']) ?>"><?= h($p['name']) ?></option><?php endforeach ?></select></label><label>С<input type="date" name="from" value="<?= h($from) ?>" required></label><label>По<input type="date" name="to" value="<?= h($to) ?>" required></label><label>Формат<select name="format"><option value="csv-v2">CSV v2 (пенсы, UTF-8)</option><option value="json-v1">JSON v1 (правила, суммы)</option></select></label><button>Зафиксировать выгрузку</button></form>
<?php foreach(array_slice($exchangeBatches??[],0,50) as $b): ?><details><summary>#<?= h($b['id']) ?> · продавец #<?= h($b['entity_id']) ?> · <?= h($b['from_on'].' — '.$b['to_on'].' · '.$b['format']) ?> · <?= h($b['decision']??'ожидает проверки') ?></summary><p>SHA-256: <code><?= h($b['payload_sha256']) ?></code> · <?= h($b['byte_count']) ?> байт</p><p><a href="<?= h(url('tax.exchange.download',['id'=>$b['id']])) ?>">Скачать зафиксированные байты</a><?php if($b['decision']): ?> · <a href="<?= h(url('tax.exchange.download',['id'=>$b['id'],'receipt'=>1])) ?>">Квитанция бухгалтера (не HMRC)</a> · <?= h($b['reference']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$b['received_at'])) ?> UTC<?php endif ?></p><?php if(!$b['decision']&&$user['role']==='accountant'&&(int)$b['created_by']!==(int)$user['id']): ?><form method="post" class="formgrid"><?php formFields('tax.exchange.receipt') ?><input type="hidden" name="id" value="<?= h($b['id']) ?>"><label>SHA-256 проверенного файла<input name="sha256" required pattern="[0-9a-f]{64}" maxlength="64"></label><label>Решение<select name="decision"><option value="accepted">Принято бухгалтером</option><option value="rejected">Отклонено</option></select></label><label>Ссылка/основание проверки<input name="reference" required maxlength="500"></label><button>Зафиксировать решение</button></form><?php endif ?></details><?php endforeach ?><?php if(count($exchangeBatches??[])>50): ?><p><a href="<?= h(url('tax',['from'=>$from,'to'=>$to,'exchange_before'=>$exchangeBatches[49]['id']])) ?>">Предыдущие выгрузки</a></p><?php endif ?></section>
